import sys, json
from mitmproxy import io
from mitmproxy.exceptions import FlowReadException
path = sys.argv[1]; mode = sys.argv[2] if len(sys.argv) > 2 else "list"
flt = sys.argv[3] if len(sys.argv) > 3 else ""
with open(path, "rb") as f:
    try:
        for fl in io.FlowReader(f).stream():
            if not hasattr(fl, "request"): continue
            r = fl.request; url = r.pretty_url
            if flt and flt not in url: continue
            code = fl.response.status_code if fl.response else (f"ERR {fl.error.msg}" if fl.error else "-")
            if mode == "list":
                size = len(fl.response.raw_content or b"") if fl.response else 0
                print(f"{r.method:6} {code} {size:>7} {url[:180]}")
            else:
                print("=" * 100); print(r.method, url, code)
                for k, v in r.headers.items(): print(f"  > {k}: {v[:200]}")
                if r.content: print("  > BODY:", r.get_text(strict=False)[:1500])
                if fl.response:
                    for k, v in fl.response.headers.items(): print(f"  < {k}: {v[:200]}")
                    print("  < BODY:", (fl.response.get_text(strict=False) or "")[:int(mode) if mode.isdigit() else 3000])
    except FlowReadException as e:
        print("read stopped:", e)
EOF
