SP="C:/Users/Wolfr/AppData/Local/Temp/claude/13fd550454c90f86/a3dc782e-6771-4c0d-a3ef-deff7c3cece6/scratchpad"; cat > "$SP/tools/gql.py" <<'EOF'
import sys, json
from mitmproxy import io
from mitmproxy.exceptions import FlowReadException
path, mode = sys.argv[1], (sys.argv[2] if len(sys.argv) > 2 else "ops")
want = sys.argv[3] if len(sys.argv) > 3 else None
seen = {}
with open(path, "rb") as f:
    try:
        for fl in io.FlowReader(f).stream():
            r = getattr(fl, "request", None)
            if not r or "nbn23.app/graphql" not in r.pretty_url: continue
            try: body = json.loads(r.get_text())
            except Exception: body = {"raw": r.get_text()[:300]}
            items = body if isinstance(body, list) else [body]
            for b in items:
                op = b.get("operationName") or (b.get("query", "")[:60].replace("\n", " "))
                if mode == "ops":
                    seen.setdefault(op, 0); seen[op] += 1
                elif op == want:
                    print("=" * 90); print("OP:", op, "VARS:", json.dumps(b.get("variables")))
                    print(b.get("query")); 
                    print("-- req headers:", {k: (v[:40] + "…" if len(v) > 40 else v) for k, v in r.headers.items()})
                    if fl.response: print("-- response (%d bytes):" % len(fl.response.content), fl.response.get_text()[:int(sys.argv[4]) if len(sys.argv) > 4 else 2500])
                    break
    except FlowReadException as e: print("read stopped:", e)
for k, v in seen.items(): print(f"{v:3}  {k}")
EOF
python "$SP/tools/gql.py" "$SP/dbbscore.flows" ops

